114	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
115	    @Override
116	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
117	        rejectMissingOrBlankFields(ownerFieldsDto);
118	        HttpHeaders headers = new HttpHeaders();
119	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
120	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
121	        owner.setEmail(normalizeEmail(owner.getEmail()));
122	        if (owner.getRegistrationDate() == null) {
123	            owner.setRegistrationDate(LocalDate.now());
124	        }
125	        rejectDuplicateTelephone(owner.getTelephone());
126	        owner.setCustomerCode(generateCustomerCode(owner.getLastName()));
127	        this.clinicService.saveOwner(owner);
128	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
129	        headers.setLocation(UriComponentsBuilder.newInstance()
130	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
131	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
132	    }
