136	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
137	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
138	        if (currentOwner == null) {
139	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
140	        }
141	        currentOwner.setAddress(ownerFieldsDto.getAddress());
142	        currentOwner.setCity(ownerFieldsDto.getCity());
143	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
144	        currentOwner.setLastName(ownerFieldsDto.getLastName());
